//! Raw libibverbs FFI bindings, generated by `build.rs` from the system rdma-core headers.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]

include!(concat!(env!("OUT_DIR"), "/ibverbs.rs"));

impl ibv_wc {
    /// The 64-bit value of the work request this completion belongs to.
    pub(crate) fn wr_id(&self) -> u64 {
        self.wr_id
    }

    /// The status and vendor error syndrome, or `None` for `IBV_WC_SUCCESS`.
    pub(crate) fn error(&self) -> Option<(ibv_wc_status::Type, u32)> {
        match self.status {
            ibv_wc_status::IBV_WC_SUCCESS => None,
            status => Some((status, self.vendor_err)),
        }
    }
}
